import {targets,vocabulary,ranking,feedback,createSemantic,submitSemantic} from './semantic.js';
export function semanticUI({main,$,state,save,toast,confirmAction,today}){
function fresh(){const box=state().extras.semantic,previous=box.current?.target;const pool=targets.filter(t=>t!==previous);const n=new Uint32Array(1);crypto.getRandomValues(n);box.current=createSemantic(pool[n[0]%pool.length],crypto.randomUUID());save();}
function record(g){const history=state().extras.semantic.history;if(g.complete&&!g.revealed&&!history.some(h=>h.id===g.id))history.push({id:g.id,date:today(),hints:g.hints});}
function submit(raw,hint=false){const g=state().extras.semantic.current;try{const rank=submitSemantic(g,raw);if(hint)g.hints++;record(g);save();render();$('#semantic-status').textContent=g.complete?'Solved in '+g.guesses.length+' guesses!':raw+' — rank '+rank+', '+feedback(rank);if(!g.complete)$('#semantic-input').focus();}catch(e){toast(e.message);}}
function render(){const box=state().extras.semantic;if(!box.current)fresh();const g=box.current,finished=g.complete||g.revealed,ranks=ranking(g.target),sorted=[...g.guesses].sort((a,b)=>ranks.get(a)-ranks.get(b)),best=sorted[0],last=g.guesses.at(-1);main.innerHTML=`<section class="section semantic"><div class="section-heading"><div class="eyebrow">Follow the meaning</div><h1>Semantic Guessing</h1><p>Find the secret word by meaning. Try “ocean”, “music”, or “home” to begin.</p></div><div class="panel"><div class="game-top"><span>${g.guesses.length} guesses · ${g.hints} hints</span><span>${best?'Best: #'+ranks.get(best):'Unlimited guesses'}</span></div><p>Lower ranks are closer. <strong>#1 is the answer.</strong> Ranks compare ${vocabulary.length.toLocaleString()} words using AI word embeddings; surprising connections can happen.</p><form id="semantic-form"><label for="semantic-input">Your guess</label><div class="semantic-entry"><input id="semantic-input" type="text" maxlength="20" autocomplete="off" autocapitalize="none" spellcheck="false" ${finished?'disabled':''}><button class="primary" ${finished?'disabled':''}>Guess</button></div></form><p id="semantic-status" role="status" aria-live="polite">${g.revealed?'Answer revealed: '+g.target.toUpperCase()+' · Not counted as a win':g.complete?'You found it: '+g.target.toUpperCase()+'!':last?'Latest: '+last+' · #'+ranks.get(last)+' · '+feedback(ranks.get(last)):'Guess a single word of any length.'}</p><div class="actions"><button class="secondary" id="semantic-hint" ${finished?'disabled':''}>Hint</button><button class="secondary" id="semantic-answer" ${finished?'disabled':''}>Show answer</button><button class="secondary" id="semantic-new">${finished?'Next puzzle':'New puzzle'}</button></div><p class="note">Hints count as guesses. Scoring works offline and your guesses stay on this device.</p></div>${sorted.length?`<div class="panel semantic-results"><h2>Your guesses · closest first</h2><ol>${sorted.map(word=>{const rank=ranks.get(word);return `<li ${word===last?'class="latest"':''}><strong>${word}</strong><span>#${rank} · ${feedback(rank)}</span><meter min="0" max="100" value="${Math.round(100*(1-Math.log(rank)/Math.log(vocabulary.length)))}" aria-label="${word}: rank ${rank}, ${feedback(rank)}"></meter></li>`;}).join('')}</ol></div>`:''}</section>`;
const input=$('#semantic-input');input.value=g.draft;input.oninput=()=>{g.draft=input.value.toLowerCase().replace(/[^a-z]/g,'').slice(0,20);input.value=g.draft;save();};$('#semantic-form').onsubmit=e=>{e.preventDefault();submit(input.value);};$('#semantic-new').onclick=()=>{const run=()=>{fresh();render();};if(g.guesses.length&&!finished)confirmAction('Start another semantic puzzle?','Your unfinished puzzle will be replaced. Completed results stay in Progress.',run);else run();};$('#semantic-answer').onclick=()=>{if(finished)return;confirmAction('Show the answer?','This ends this puzzle and will not count as a win.',()=>{if(g.complete||g.revealed)return;g.revealed=true;save();render();});};if(!finished)$('#semantic-hint').onclick=()=>{const ceiling=best?ranks.get(best):vocabulary.length+1;const choices=[...ranks].filter(([w,r])=>r>1&&r<ceiling&&!g.guesses.includes(w)).sort((a,b)=>b[1]-a[1]);const desired=Math.max(1,Math.floor(ceiling/2));const chosen=choices.find(([,r])=>r<=desired)||choices.at(-1);if(chosen)submit(chosen[0],true);else toast('You have the closest word. Try the answer, or tap Show answer.');};}
return {render};}
